package com.powerliq.valuation;
import com.fasterxml.jackson.databind.ObjectMapper;import com.powerliq.api.contracts.ServiceException;import com.powerliq.financial.*;import com.powerliq.valuation.ValuationModels.*;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.Timestamp;import java.time.*;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ValuationApplicationService{
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final ValuationEngine engine;private final Clock clock;
 public ValuationApplicationService(JdbcTemplate j,ObjectMapper o,ValuationEngine e,Clock c){jdbc=j;json=o;engine=e;clock=c;}
 @Transactional public Result calculate(String key,Request request){if(key==null||key.isBlank()||key.length()>128)throw new ServiceException(ValuationErrorCode.IDEMPOTENCY_KEY_REQUIRED,"A valid Idempotency-Key is required");validate(request);String hash=hash(request);var existing=jdbc.query("SELECT input_hash,result_json FROM valuations WHERE idempotency_key=?",(r,n)->Map.entry(r.getString(1),r.getString(2)),key).stream().findFirst();if(existing.isPresent()){if(!existing.get().getKey().equals(hash))throw new ServiceException(ValuationErrorCode.IDEMPOTENCY_CONFLICT,"Idempotency key was used for different inputs");return read(existing.get().getValue());}
  try{List<Position> positions=request.positions().stream().map(this::position).toList();Map<SettlementInterval,MarketPrice> prices=request.prices().stream().map(this::price).collect(Collectors.toMap(MarketPrice::settlementInterval,Function.identity(),(a,b)->b));PortfolioValuation value=engine.value(positions,prices);Instant calculated=Instant.now(clock);Result result=new Result(UUID.randomUUID(),request.portfolioId(),request.asOf(),calculated,hash,value.positions().stream().map(v->new PositionResult(v.positionId(),v.mtm().value(),v.collateral().value())).toList(),value.portfolioMtm().value(),value.estimatedCollateral().value());String input=json.writeValueAsString(request);String output=json.writeValueAsString(result);jdbc.update("INSERT INTO valuations(id,idempotency_key,input_hash,portfolio_id,as_of,calculated_at,input_json,result_json) VALUES(?,?,?,?,?,?,?::jsonb,?::jsonb)",result.id(),key,hash,result.portfolioId(),Timestamp.from(result.asOf()),Timestamp.from(calculated),input,output);return result;}catch(IncompleteValuationException e){throw new ServiceException(ValuationErrorCode.MARKET_DATA_INCOMPLETE,e.getMessage());}catch(ServiceException e){throw e;}catch(Exception e){throw new ServiceException(ValuationErrorCode.VALUATION_INVALID,e.getMessage());}}
 @Transactional(readOnly=true)public Result find(UUID id){return jdbc.query("SELECT result_json FROM valuations WHERE id=?",(r,n)->read(r.getString(1)),id).stream().findFirst().orElseThrow(()->new ServiceException(ValuationErrorCode.VALUATION_NOT_FOUND,"Valuation was not found"));}
 private Position position(PositionInput p){return new Position(p.id(),p.portfolioId(),p.side(),new PriceGbpPerMWh(p.contractPriceGbpPerMWh()),new EnergyMWh(p.volumeMWh()),SettlementInterval.of(p.settlementDate(),p.settlementPeriod()),PositionStatus.ACTIVE,p.createdAt());}
 private MarketPrice price(PriceInput p){return new MarketPrice(p.provider(),SettlementInterval.of(p.settlementDate(),p.settlementPeriod()),new PriceGbpPerMWh(p.priceGbpPerMWh()),p.sourceTimestamp(),p.retrievedAt());}
 private void validate(Request r){if(r==null||r.portfolioId()==null||r.asOf()==null||r.positions()==null||r.prices()==null||r.positions().isEmpty()||r.positions().size()>10000||r.prices().size()>10000||r.positions().stream().anyMatch(p->!r.portfolioId().equals(p.portfolioId())))throw new ServiceException(ValuationErrorCode.VALUATION_INVALID,"Valuation requires one portfolio and at most 10,000 positions and prices");}
 private String hash(Request r){try{String canonical=json.writeValueAsString(new Request(r.portfolioId(),r.asOf(),r.positions().stream().sorted(Comparator.comparing(PositionInput::id)).toList(),r.prices().stream().sorted(Comparator.comparing(PriceInput::settlementDate).thenComparingInt(PriceInput::settlementPeriod).thenComparing(PriceInput::provider)).toList()));return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Result read(String value){try{return json.readValue(value,Result.class);}catch(Exception e){throw new IllegalStateException("Stored valuation is unreadable",e);}}
}
